create or replace function public.link_recruiting_campaign_job() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$ declare p public.recruiting_campaigns%rowtype; begin select * into p from public.recruiting_campaigns where owner_user_id=new.owner_user_id and campaign_key=new.campaign_key; if p.id is null then return new; end if; insert into public.recruiting_campaign_messages(campaign_id,owner_user_id,contact_id,stage,subject,body,tracking_id) select p.id,p.owner_user_id,t.contact_id,'initial',new.subject,new.body,new.tracking_id from public.recruiting_campaign_contacts t where t.campaign_id=p.id and t.contact_id=any(new.contact_ids) on conflict(campaign_id,contact_id,stage) do update set tracking_id=excluded.tracking_id,subject=excluded.subject,body=excluded.body; return new; end $$; create trigger link_initial_job_campaign after insert or update of tracking_id,status on public.recruiting_initial_email_jobs for each row execute function public.link_recruiting_campaign_job();